import csv, re

rows = list(csv.DictReader(open('/work/documents/bank_checking_2024-12_to_2026-01.csv')))
out = [["date","description","amount","classification","schedule_c_line","note"]]

def cls(r):
    d, desc, amt = r["date"], r["description"], r["amount"]
    a = float(amt)
    if d.startswith("2024"):
        if "TESSARO" in desc:
            return ("prior_year","", "Received 12/27/2024 (INV 1041) — belongs on the 2024 return per the cash-method rule in the Schedule C instructions excerpt; not part of 2025 line 1 (Tessaro 1099-NEC $9,400 = the four 2025 receipts only).")
        return ("prior_year","", "December 2024 personal spending — outside tax year 2025.")
    if "PAYHUB" in desc:
        return ("business_income","1", "PayHub payout; 1099-K gross $41,350 reported at gross on line 1, processor fees $1,199.15 to line 10.")
    if "TESSARO" in desc:
        return ("business_income","1", "Direct client ACH receipt, substantiated in bank; ties to Tessaro 1099-NEC ($9,400 total for 2025).")
    if "LARKSPUR" in desc:
        return ("other_schedule","", "W-2 wage deposit (Larkspur Interactive); wages $24,800 go on Form 1040, not Schedule C.")
    if "T-MOBILE" in desc:
        return ("business_expense","25", "ASSUMPTION: 50% business use (unsupported in file); $1,020/yr × 50% = $510 on line 25.")
    if "SPECTRUM" in desc:
        return ("business_expense","25", "ASSUMPTION: 50% business use (unsupported in file); $840/yr × 50% = $420 on line 25.")
    if "HISCOX" in desc:
        return ("business_expense","15", "Professional liability insurance — line 15 (insurance other than health).")
    if "BLUE CROSS" in desc:
        return ("other_schedule","", "Health insurance premium — NOT deductible on Schedule C; Schedule 1 line 17 (SE health insurance), per Schedule C instructions excerpt. Eligibility open item.")
    if "CAPITAL FACTORY" in desc:
        return ("business_expense","20b", "Coworking rent, line 20b per Schedule C instructions excerpt. Routine trips here are commuting (nondeductible) on the mileage side.")
    if "IRS USATAXPYMT" in desc:
        q = desc[-2:]
        return ("tax_payment","", "2025 federal estimated tax payment Q%s; reported as tax payments on the individual return, not a business expense." % q)
    if "FIGMA" in desc:
        return ("business_expense","27a", "Software subscription; ASSUMPTION: 100% business (design tool); $540/yr in line 27a total.")
    if "ADOBE" in desc:
        return ("business_expense","27a", "Software subscription; ASSUMPTION: 100% business (design tool); $719.88/yr in line 27a total.")
    if "APPLE.COM/BILL" in desc:
        return ("business_expense","27a", "ASSUMPTION: 100% business use; de minimis safe harbor election ($2,149 ≤ $2,500 per Schedule C instructions excerpt line 13); election statement required.")
    if "SOUTHWEST AIR 526" in desc or "HOTEL ZEPHYR" in desc:
        return ("business_expense","24a", "ASSUMPTION: primarily business travel to DESIGNWEEK SF; Pub 463 denies primarily-personal travel.")
    if "DESIGNWEEK" in desc:
        return ("business_expense","27a", "Professional development (conference registration) — line 27a per Schedule C instructions excerpt.")
    if "MARINA DELI" in desc or "TARTINE" in desc:
        return ("business_expense","24b", "ASSUMPTION: business meal while traveling away from home; only 50% deductible (Pub 463 / Schedule C line 24b).")
    if "SOUTHWEST AIR 118" in desc:
        return ("personal","", "Austin–Denver flight 6/13/2025: no business purpose documented anywhere in the file; deducted nowhere pending client explanation (open item).")
    if "ZELLE TO: M. OKAFOR" in desc:
        return ("personal","", "Personal rent to family member; nondeductible (IRC §262(a)); no home office claimed.")
    if "NETFLIX" in desc or "ORANGETHEORY" in desc:
        return ("personal","", "Personal subscription/gym — nondeductible (IRC §262(a)).")
    if "H-E-B" in desc:
        return ("personal","", "Groceries — personal, nondeductible (IRC §262(a)).")
    if "VENMO" in desc:
        return ("personal","", "Wedding gift — personal expense (IRC §262(a)).")
    return ("personal","", "Unclassified — flagged for review.")

for r in rows:
    c, line, note = cls(r)
    out.append([r["date"], r["description"], r["amount"], c, line, note])

with open('/work/deliverable/classification.csv','w',newline='') as f:
    csv.writer(f).writerows(out)

# sanity totals
from decimal import Decimal as D
import collections
data = out[1:]
tot = collections.defaultdict(D)
for d,desc,amt,c,l,n in data:
    tot[c] += D(amt)
for k,v in tot.items(): print(k, v)
print("rows:", len(data))
EOF

